/// The contents of the LAST quoted string in `s` (the import source sits at the end).
pub(crate) fn quoted_last(s: &str) -> Option<String> {
    for q in ['"', '\''] {
        if let Some(close) = s.rfind(q) {
            if let Some(open) = s[..close].rfind(q) {
                return Some(s[open + 1..close].to_string());
            }
        }
    }
    None
}
